export function invariant(value, message) {
  if (value == null) {
    throw new Error(message);
  }
  return value;
}

// Open source, but exact targets allocated elsewhere in this package. Neither
// target is the router state or location literal. The second joins the local
// result's assignments through Object.assign's exact target-return identity.
export function assignUnrelated(source) {
  const unrelated = {};
  Object.assign(unrelated, source);
  let result;
  result = Object.assign(result || { ...source }, source);
  return result;
}
